// Approved P1/P2 English consultation handoff.
if ((treatment === 'P1' || treatment === 'P2') && locale === 'en') {
  const consult = container.querySelector('.consult-inner');
  if (consult) {
    const notice = document.createElement('p');
    notice.id = 'partner-contact-language';
    notice.textContent = 'Opens Digiwin Vietnam’s consultation page in Vietnamese.';
    const contact = document.createElement('a');
    contact.id = 'partner-contact-cta';
    contact.className = 'cta';
    contact.href = 'https://www.digiwin.com.vn/contact-vn/';
    contact.setAttribute('aria-describedby', notice.id);
    contact.textContent = 'Discuss your factory workflow';
    consult.append(notice, contact);
  }
}

document.documentElement.lang = locale;
